"""
Synthetic multi-day workload construction (v2 Section 7.6).

"Sessions are generated by interleaving task episodes drawn from a mixture
of domains (customer support, coding assistance, and personal-assistant
style interactions), with injected topic drift, contradictory updates, and
[duplicates]."

This generator produces a flat, timestamped event stream (dicts with
subject/value/source/confidence/domain/kind) rather than natural-language
text, consistent with the reference implementation's symbolic memory model
(memory/record.py) -- the mixture-of-domains, drift, contradiction, and
duplicate *rates* are what the experiments manipulate and measure, and
those are real controllable, reportable parameters independent of whether
the underlying content is natural language or a symbolic surrogate.
"""
from __future__ import annotations

import random
from dataclasses import dataclass, field

DOMAINS = ("customer_support", "coding_assistance", "personal_assistant")
SOURCES = ("user", "tool", "user_correction")


@dataclass
class WorkloadConfig:
    n_events: int = 1500
    n_subjects: int = 40
    duplicate_rate: float = 0.15
    contradiction_rate: float = 0.10
    drift_rate: float = 0.05     # probability an event introduces a brand-new subject
    seed: int = 0
    dt_min: float = 0.2
    dt_max: float = 4.0


def generate_workload(config: WorkloadConfig) -> list[dict]:
    rng = random.Random(config.seed)
    base_subjects = [f"subject_{i:03d}" for i in range(config.n_subjects)]
    drift_pool: list[str] = []
    last_value: dict[str, str] = {}

    events = []
    t = 0.0
    for i in range(config.n_events):
        t += rng.uniform(config.dt_min, config.dt_max)
        domain = rng.choice(DOMAINS)

        if rng.random() < config.drift_rate:
            subj = f"drift_{len(drift_pool):04d}"
            drift_pool.append(subj)
        else:
            pool = base_subjects + drift_pool
            subj = rng.choice(pool)

        roll = rng.random()
        if subj in last_value and roll < config.duplicate_rate:
            value = last_value[subj]
            kind = "duplicate"
        elif subj in last_value and roll < config.duplicate_rate + config.contradiction_rate:
            value = f"val_{rng.randint(0, 100_000)}"
            kind = "contradiction"
        else:
            value = f"val_{rng.randint(0, 100_000)}"
            kind = "fresh"

        last_value[subj] = value
        source = rng.choices(SOURCES, weights=(0.7, 0.2, 0.1))[0]
        confidence = round(rng.uniform(0.45, 0.97), 3)

        events.append({
            "seq": i, "ts": t, "subject": subj, "value": value, "source": source,
            "confidence": confidence, "domain": domain, "kind": kind,
        })
    return events


def split_days(events: list[dict], events_per_day: int = 300) -> list[list[dict]]:
    return [events[i:i + events_per_day] for i in range(0, len(events), events_per_day)]
